def find_pattern(files, to_delete):
    n = len(files)
    m = len(to_delete)

    # Create sets of characters at each position for files to keep and files to delete
    keep_chars = [set() for _ in range(101)]
    delete_chars = [set() for _ in range(101)]

    for i in range(n):
        if i + 1 in to_delete:
            for j, char in enumerate(files[i]):
                delete_chars[j].add(char)
        else:
            for j, char in enumerate(files[i]):
                keep_chars[j].add(char)

    # Check if there is a common pattern
    pattern = []
    for i in range(101):
        if not keep_chars[i] and not delete_chars[i]:
            pattern.append('.')
        elif keep_chars[i] and not delete_chars[i]:
            pattern.append('?')
        elif not keep_chars[i] and delete_chars[i]:
            return 'No'
