def find_pattern(filenames, indices_to_delete):
    # Extract the filenames that need to be deleted and the ones that remain
    files_to_delete = [filenames[i-1] for i in indices_to_delete]
    remaining_files = [filenames[i-1] for i in range(1, len(filenames)+1) if i not in indices_to_delete]

    # Determine the maximum possible pattern length based on the remaining files
    max_length = max(len(file) for file in remaining_files)

    # Try to construct a pattern that fits the files to be deleted
    for length in range(1, max_length + 1):
        pattern = [''] * length
        mismatched_chars = set()

        for i in range(length):
            seen_chars = set()
            for file in remaining_files:
                if i < len(file):
                    char = file[i]
                    if char not in seen_chars:
                        seen_chars.add(char)
                        pattern[i] = char

            if len(seen_chars) > 1:
                pattern[i] = '?'
                mismatched_chars.add(i)

        # Check if the constructed pattern matches all files to be deleted
        valid_pattern = True
        for file in files_to_delete:
            if len(file) != length:
                continue
            for i in range(length):
                if i in mismatched_chars:
                    continue
                if file[i] != pattern[i]:
                    valid_pattern = False
                    break

        if valid_pattern:
            return 'Yes\n' + ''.join(pattern)

    return 'No'

