        return "No"

    first_file = filenames[indices[0] - 1]
    last_file = filenames[indices[-1] - 1]

    if len(first_file) != len(last_file):
        return "No"

    pattern = []
    for i in range(len(first_file)):
        if first_file[i] != last_file[i]:
            pattern.append('?')
        else:
            pattern.append(first_file[i])

    pattern_str = ''.join(pattern)

    # Verify the pattern
    valid = True
    for file in filenames:
        if len(file) != len(pattern_str):
            continue
        match = True
        for j in range(len(file)):
            if pattern_str[j] != '?' and file[j] != pattern_str[j]:
                match = False
                break
        if match:
            if file not in [filenames[i-1] for i in indices]:
                valid = False
                break

    if valid:
        return "Yes\n" + pattern_str
    else:
        return "No"

